local M = class("FulwinArenaBattleLogPopControl", LikeOO.OOControlBase)

function M:onEnter()

end

function M:onHandle(msg, data)
    if msg == 99999 then -- 关闭
        self:closeView()
    elseif msg == "check_tag" then
        self:switchTabBtn(data)
    elseif msg == "play_video" then
        self:openView("HuashanSword.HuashanSwordBattleDetail", {battle_id = data.battle_id, log_data = data.log_data})
        --local function callback(response)
        --    if response then
        --        self:openView("Pops.BattleStatistics", {data = response, round = data.index, log_data = data.log_data})
        --    end
        --end
        --self.m_model:getNetData("battle_replay", {battle_id = data.battle_id}, callback)
    end
end

function M:activityOverExamine(response)
    if response["end"] == 1 then
        GameUtil:lookInfoTips(self, {msg = Language:getTextByKey("gf_str_0085"), delay_close = 2})
        self:closeView()
        return true
    end
    return false
end

-- 按钮切换
function M:switchTabBtn(index)
    if self.m_model.m_selectIndex ~= index then
        self.m_model:setSelectIndex(index)
        local function callfunc(response)
            --Logger.log(response,"switchTabBtn response ===")
            if self.m_view then
                self.m_model:updateData(response)
                self.m_view:refreshUI()
            end
        end
        self.m_model:getNetData("friend_arena_logs",{typ = index - 1}, callfunc)
    end
end

return M